window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"Ask6M7eySMM","speaker":"Judith Suminwa Tuluka","role":"Prime Minister","country":"Democratic Republic of the Congo","region":"Africa","url":"https://www.youtube.com/watch?v=Ask6M7eySMM","date":"20260924","title":"🇨🇩 Democratic Republic of the Congo - Prime Minister Addresses UN General Assembly 81st Session","seconds":1705,"words":3620,"counts":{"claims":50,"promises":4,"attacks":1},"topics":[{"topic":"Democratic Republic of the Congo mining policy","share":0.1136,"seconds":194},{"topic":"Democratic Republic of the Congo peace process","share":0.0853,"seconds":145},{"topic":"Democratic Republic of the Congo education","share":0.0749,"seconds":128},{"topic":"United Nations Security Council reform","share":0.0407,"seconds":69},{"topic":"Democratic Republic of the Congo green economy","share":0.0399,"seconds":68},{"topic":"United Nations General Assembly","share":0.0399,"seconds":68},{"topic":"Democratic Republic of the Congo international relations","share":0.0397,"seconds":68},{"topic":"Democratic Republic of the Congo labor","share":0.0397,"seconds":68},{"topic":"Multilateral cooperation","share":0.0392,"seconds":67},{"topic":"Climate disruptions","share":0.0389,"seconds":66},{"topic":"Democratic Republic of the Congo conflict","share":0.0381,"seconds":65},{"topic":"Democratic Republic of the Congo climate finance","share":0.0379,"seconds":65},{"topic":"Democratic Republic of the Congo infrastructure","share":0.0378,"seconds":64},{"topic":"AI governance","share":0.0378,"seconds":64},{"topic":"International development aid","share":0.0377,"seconds":64},{"topic":"United Nations reform","share":0.0375,"seconds":64},{"topic":"Democratic Republic of the Congo development strategy","share":0.0373,"seconds":64},{"topic":"United Nations trust funds","share":0.0372,"seconds":63},{"topic":"Democratic Republic of the Congo resource management","share":0.0369,"seconds":63},{"topic":"Democratic Republic of the Congo armed groups","share":0.0368,"seconds":63},{"topic":"Democratic Republic of the Congo territorial integrity","share":0.0366,"seconds":62},{"topic":"Democratic Republic of the Congo health","share":0.0365,"seconds":62}],"timeline":[[3,66,"Democratic Republic of the Congo development strategy"],[67,135,"United Nations General Assembly"],[135,202,"Multilateral cooperation"],[204,268,"United Nations trust funds"],[269,333,"AI governance"],[334,403,"United Nations Security Council reform"],[404,471,"Democratic Republic of the Congo international relations"],[473,538,"Democratic Republic of the Congo conflict"],[541,611,"Democratic Republic of the Congo peace process"],[613,676,"Democratic Republic of the Congo armed groups"],[676,752,"Democratic Republic of the Congo peace process"],[753,815,"Democratic Republic of the Congo territorial integrity"],[817,883,"Democratic Republic of the Congo mining policy"],[885,947,"Democratic Republic of the Congo mining policy"],[949,1014,"Democratic Republic of the Congo mining policy"],[1015,1083,"Democratic Republic of the Congo labor"],[1083,1148,"Democratic Republic of the Congo infrastructure"],[1148,1213,"Democratic Republic of the Congo education"],[1215,1277,"Democratic Republic of the Congo education"],[1278,1340,"Democratic Republic of the Congo health"],[1341,1407,"Climate disruptions"],[1408,1473,"Democratic Republic of the Congo climate finance"],[1473,1541,"Democratic Republic of the Congo green economy"],[1542,1607,"International development aid"],[1607,1670,"Democratic Republic of the Congo resource management"],[1671,1735,"United Nations reform"],[1736,1749,null]],"stances":{"Democratic Republic of the Congo development strategy":"Judith Suminwa Tuluka conveys the Congolese vision of the future on behalf of President Felix Tshisekedi.","United Nations General Assembly":"Judith Suminwa Tuluka pays tribute to the newly elected president, the previous session's president, and the Secretary-General while affirming the session's theme of restoring trust.","Multilateral cooperation":"Judith Suminwa Tuluka calls for a clear-eyed evaluation of the UN's ability to evolve and highlights inconsistencies in how international cooperation is applied across different crises.","United Nations trust funds":"Judith Suminwa Tuluka argues that lasting trust in the UN is impossible when principles are applied selectively and the organization reflects an outdated world.","AI governance":"Judith Suminwa Tuluka argues that AI governance must include developing countries and avoid being controlled solely by specific powers or corporations.","United Nations Security Council reform":"Judith Suminwa Tuluka asserts that Africa is currently inadequately represented in global decision-making and calls for the admission of two permanent seats with veto rights and two non-permanent seats to make the council more representative, legitimate, and effective.","Democratic Republic of the Congo international relations":"The DRC supports the candidacy of Miss Juliana Amatulum Mumba for Secretary General of the Organisation internationale de la Francophonie as a means to transform the organization and strengthen trust among members.","Democratic Republic of the Congo conflict":"Judith Suminwa Tuluka states that the eastern DRC suffers from decades of violence, resource looting, and a war of aggression led by Rwanda.","Democratic Republic of the Congo peace process":"Judith Suminwa Tuluka states that while diplomatic efforts and international support have been made, the promised peace remains unfulfilled for millions of Congolese.","Democratic Republic of the Congo armed groups":"The speaker asserts that the FDLR issue should no longer justify foreign military presence in the DRC and highlights the implementation of a disarmament protocol.","Democratic Republic of the Congo territorial integrity":"Judith Suminwa Tuluka asserts that internal dialogue must address structural vulnerabilities while acknowledging that external aggression cannot be dismissed as a domestic issue, emphasizing that national cohesion and defense of territory are complementary.","Democratic Republic of the Congo mining policy":"Judith Suminwa Tuluka argues that the governance of strategic resources must be linked to peace, development, and global security due to the DRC's central role in supplying minerals for the global energy transition.","Democratic Republic of the Congo labor":"The speaker asserts that achieving zero children in mines is a shared responsibility involving the state, businesses, and markets, and proposes a global framework for traceable mineral value chains.","Democratic Republic of the Congo infrastructure":"Judith Suminwa Tuluka advocates for a mineral corridor that ensures traceability, worker protection, and local value addition rather than merely exporting raw materials.","Democratic Republic of the Congo education":"Judith Suminwa Tuluka states that the DRC has implemented free primary education since 2019, resulting in significant increases in school enrollment.","Democratic Republic of the Congo health":"The speaker states that fighting the Ebola epidemic is an absolute priority for the DRC and highlights recent tangible results from national mobilization and partner support.","Climate disruptions":"Judith Suminwa Tuluka states that climate disruptions are putting societies under pressure and notes the paradox where countries contributing least to global warming suffer the heaviest consequences.","Democratic Republic of the Congo climate finance":"Judith Suminwa Tuluka argues that climate finance for the DRC must be accessible, predictable, and proportionate to ecosystem services provided, while avoiding further indebtedness of communities that protect the environment.","Democratic Republic of the Congo green economy":"The speaker states that the DRC aims to create 25,000 jobs and protect 5,000 square kilometers of forest by 2027 while proposing an African coalition for water security.","International development aid":"The speaker states that official development aid has fallen significantly, undermining development efforts and emphasizing the need for better access to financing, debt relief, and tax justice.","Democratic Republic of the Congo resource management":"Judith Suminwa Tuluka states that the DRC aims to use its recovered resources and natural wealth as a foundation for shared prosperity while emphasizing that national transformation requires an international order where principles are equally applied.","United Nations reform":"Judith Suminwa Tuluka argues that restoring trust in the UN requires applying international law consistently and ensuring equitable benefit sharing, while asserting the DRC's commitment to contributing to this transformation."},"claims":[{"t":47,"quote":"it is my privilege to convey from this rostrm on behalf of his excellency Mr. Felix Antoine Chis Chumbo, president of the DRC and head of state, the Congalles vision of the future of our","topic":"Democratic Republic of the Congo development strategy","kind":"fact"},{"t":67,"quote":"Khalilur Rakman on his election as president of this 81st session of the general assembly.","topic":"United Nations General Assembly","kind":"fact"},{"t":76,"quote":"I also pay tribute to her excellency Miss Anelina Bearbuk for the work she accomplished during the previous session.","topic":"United Nations General Assembly","kind":"self_credit"},{"t":86,"quote":"Lastly, I pay tribute in particular to Mr. Antonio Gutish, Secretary General of the United Nations, at a time when his mandate is coming to its end.","topic":"United Nations General Assembly","kind":"fact"},{"t":137,"quote":"This session is another occasion to reaffirm its faith in a multilateralism based upon the unwavering quest for peace and justice which paved the way not to the prosperity of a select few but to the creation of a true common horizon for peoples and generations of the future.","topic":"Multilateral cooperation","kind":"fact"},{"t":190,"quote":"When territorial integrity is vigorously defended in one crisis but seems negotiable in another. when the suffering of civilians calls for immediate action in one place but seems less urgent in another.","topic":"Multilateral cooperation","kind":"fact"},{"t":204,"quote":"In reality, there can be no lasting trust when the force of our principles varies depending on the people's crises or circumstances.","topic":"United Nations trust funds","kind":"fact"},{"t":256,"quote":"It cannot speak of restoring trust toward the UN, let alone of a as long as the UN continues to reflect a world that has ceased to exist.","topic":"United Nations trust funds","kind":"fact"},{"t":269,"quote":"The world of 1945 no longer exists. Digital revolution, energy transition, and climate disregulation are now altering equilibria.","topic":"AI governance","kind":"fact"},{"t":287,"quote":"Artificial intelligence today offers one of the most striking examples of this. It has immense potential but also poses risk of new fractures.","topic":"AI governance","kind":"fact"},{"t":334,"quote":"Africa has proven itself over time to be a demographic, diplomatic and geopolitical power, a vital one, but it still remains inadequately represented where decisions are being made about the world's future.","topic":"United Nations Security Council reform","kind":"fact"},{"t":361,"quote":"The admission of the African Union to G20 is certainly a major step in the right direction.","topic":"United Nations Security Council reform","kind":"fact"},{"t":374,"quote":"As a member of the security council 2026 2027, we reaffirm our support for the common African position enshrined in the Ezelini consensus and the seir declaration that is to say two permanent seats for Africa with all of the associated privileges including veto rights as long as they exist and two non-permanent additional in order to make the council more representative, more legitimate and ultimately more effective.","topic":"United Nations Security Council reform","kind":"self_credit"},{"t":412,"quote":"the DRC intends to fully exercise its responsibility when it comes to choosing the next general whose mandate ought to be part of the transformation of our organization","topic":"Democratic Republic of the Congo international relations","kind":"fact"},{"t":430,"quote":"This same ambition is our driving force within the franophhone world through the candidacy of Miss Juliana Amatulum Mumba for the position of secretary general of the O","topic":"Democratic Republic of the Congo international relations","kind":"fact"},{"t":485,"quote":"For more than three decades, millions of have been suffering attacks, forced displacement, and bereavement.","topic":"Democratic Republic of the Congo conflict","kind":"fact"},{"t":514,"quote":"My country continues to face a war of aggression led by Rwanda through its proxy, the AFCM23, in violation of its sovereignty, our sovereignty, and our territorial integrity as documented by the UN.","topic":"Democratic Republic of the Congo conflict","kind":"fact"},{"t":548,"quote":"The peace agreement signed to Washington on June 27, 2025.","topic":"Democratic Republic of the Congo peace process","kind":"fact"},{"t":582,"quote":"Resolution 2773 of the Security Council has laid out an unambiguous path.","topic":"Democratic Republic of the Congo peace process","kind":"fact"},{"t":636,"quote":"the protocol signed by the political and military leadership of the FDLR on May 30th, 2026 provides for the disarmament, demobilization, and containment of their combatants","topic":"Democratic Republic of the Congo armed groups","kind":"fact"},{"t":659,"quote":"The repatriation on September 8th with support of Monusco 120 persons associated with the FDLR is a first testament to the protocol's implementation","topic":"Democratic Republic of the Congo armed groups","kind":"number"},{"t":743,"quote":"the president of the DRC launched on August 28th a national dialogue for peace, cohesion, and the rebuilding of the state.","topic":"Democratic Republic of the Congo peace process","kind":"fact"},{"t":753,"quote":"This dialogue is open to the political and social forces that are committed to the republic, our constitution, our territorial integrity, and to the rejection of violence.","topic":"Democratic Republic of the Congo territorial integrity","kind":"fact"},{"t":796,"quote":"no internal dialogue can transform an external aggression into a simple domestic dispute.","topic":"Democratic Republic of the Congo territorial integrity","kind":"fact"},{"t":858,"quote":"The energy transition, the electrification of transport, energy storage, as well as the expansion of digital and AI infrastructure are accelerating demand for copper, cobalt, lithium, nickel, and other critical minerals.","topic":"Democratic Republic of the Congo mining policy","kind":"fact"},{"t":875,"quote":"As the largest global producer of cobalt and a major copper producing power, the DRC is at the heart of the transformation.","topic":"Democratic Republic of the Congo mining policy","kind":"fact"},{"t":885,"quote":"Congolese cobalt is already being used in batteries, power grids, digital equipment, and technologies that are crucial for the decarbonization of the global economy.","topic":"Democratic Republic of the Congo mining policy","kind":"fact"},{"t":924,"quote":"The DRC therefore refuses the old rejects the old model that limits producer countries to crude extraction while processing research technology and the bulk of the profits are concentrated elsewhere.","topic":"Democratic Republic of the Congo mining policy","kind":"fact"},{"t":981,"quote":"The DRC is pursuing the modernization of mining governance through the transparency of contracts, extractive revenue, and effective beneficiaries. improving mining registries, the deployment of traceability mechanisms, and the fight against fraud.","topic":"Democratic Republic of the Congo mining policy","kind":"fact"},{"t":1015,"quote":"Together with the International Labor Organization, UNICEF, and our other partners, we are strengthening our identification monitoring and remediation mechanisms as well as the training of our inspectors, school attendance of children and economic solutions for their families.","topic":"Democratic Republic of the Congo labor","kind":"fact"},{"t":1031,"quote":"Our goal is unambiguous. We need to achieve zero children in the mines.","topic":"Democratic Republic of the Congo labor","kind":"fact"},{"t":1083,"quote":"It ought to guarantee traceability of minerals, responsibility of economic actors, protection of workers and communities as well as a more equitable sharing of added value thanks to local processing and technology transfer.","topic":"Democratic Republic of the Congo infrastructure","kind":"fact"},{"t":1118,"quote":"The rehabilitation of railway links, the modernization of infrastructure, the facilitation of exchange and energy investments can connect our territories, reduce logistical costs, and stimulate regional trade.","topic":"Democratic Republic of the Congo infrastructure","kind":"fact"},{"t":1193,"quote":"Since 2019, we have had free primary education, enabling more than 5 million additional children to attend school.","topic":"Democratic Republic of the Congo education","kind":"number"},{"t":1200,"quote":"In the 2020 2024 school year, more than 21 million children were enrolled in primary school compared with 14.7 four years earlier.","topic":"Democratic Republic of the Congo education","kind":"number"},{"t":1219,"quote":"We are continuing to build and rehabilitate schools. And recently, we've begun to roll out school cafeterias because access is not enough.","topic":"Democratic Republic of the Congo education","kind":"fact"},{"t":1251,"quote":"We're continuing the gradual expansion of universal health coverage in particular through free maternity care, improved maternal and newborn care, vaccination, access to essential medicines, the strengthening of the health care workforce, and by expanding social protections.","topic":"Democratic Republic of the Congo education","kind":"fact"},{"t":1311,"quote":"After having contained 16 previous outbreaks, the DRC is mobilizing recognized scientific and operational expertise.","topic":"Democratic Republic of the Congo health","kind":"fact"},{"t":1319,"quote":"And thanks to national mobilization and the support of our partners, the response has recently begun producing tangible results.","topic":"Democratic Republic of the Congo health","kind":"self_credit"},{"t":1377,"quote":"flooding, droughts, and erosion. Not to mention population displacement are threatening our stability.","topic":"Climate disruptions","kind":"fact"},{"t":1392,"quote":"Those who contribute least to global warming often suffer the heaviest consequences.","topic":"Climate disruptions","kind":"fact"},{"t":1408,"quote":"The DRC is one of these custodians. It is home to a vital part of the Congo basin which is one of the planet's greatest climate regulators.","topic":"Democratic Republic of the Congo climate finance","kind":"fact"},{"t":1457,"quote":"This ambition is taking shape especially through the Kivu Kinshasa green corridor which combines existent preservation, economic development and improve living conditions of the people generating 60 megawatts of electricity.","topic":"Democratic Republic of the Congo climate finance","kind":"number"},{"t":1473,"quote":"This initiative also aims by 2027 to create 25,000 jobs and protect 5,000 square kilometers of natural forest.","topic":"Democratic Republic of the Congo green economy","kind":"number"},{"t":1518,"quote":"the Congoles roadmap for accelerating the estimates our needs at more than 7 billion dollars.","topic":"Democratic Republic of the Congo green economy","kind":"number"},{"t":1544,"quote":"official development aid has fallen by more than 23% in real terms in 2025, which is the steepest annual contraction ever recorded.","topic":"International development aid","kind":"number"},{"t":1607,"quote":"Every penny recovered can fund a vaccine, a a well, or a road.","topic":"Democratic Republic of the Congo resource management","kind":"fact"},{"t":1628,"quote":"That is the goal of our efforts to consolidate peace, strengthen our institutions, and make our natural and human wealth the foundation of shared prosperity.","topic":"Democratic Republic of the Congo resource management","kind":"self_credit"},{"t":1680,"quote":"Restoring trust means applying the law even when it is costly, not only when it is convenient.","topic":"United Nations reform","kind":"fact"},{"t":1704,"quote":"The DRC intends to play its full role in this effort.","topic":"United Nations reform","kind":"self_credit"}],"promises":[{"t":718,"quote":"The DRC, for its part, will continue to fully shoulder its responsibility, especially through pursuing reforms of its defense and security institutions, through bolstering state authority, and through reconstruction on territories affected by the conflicts.","topic":"Democratic Republic of the Congo peace process","kind":"promise"},{"t":942,"quote":"We plan to become a workshop, a laboratory, and a sovereign partner.","topic":"Democratic Republic of the Congo mining policy","kind":"promise"},{"t":1062,"quote":"That is why the DRC proposes creating under UN opaces and together with the African Union as well as producer, processor and consumer countries a global framework for just traceable and resilient critical mineral value chains based upon the sovereignty of producer states.","topic":"Democratic Republic of the Congo labor","kind":"promise"},{"t":1709,"quote":"At the heart of Africa, it will pursue its own transformation while contributing to that of our organization.","topic":"United Nations reform","kind":"promise"}],"attacks":[{"t":516,"quote":"war of aggression led by Rwanda through its proxy, the AFCM23","topic":"Democratic Republic of the Congo conflict","target":"Rwanda"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":3,"topic":"Democratic Republic of the Congo development strategy","text":"The assembly will hear an address by her excellency Judith Sumunawa Tula, pres prime minister, head of government of the Democratic Republic of Congo. I request protocol to escort her excellency and invite her to address the &gt;&gt; Mr. President, Secretary General, excellencies, distinguished heads of state and it is my privilege to convey from this rostrm on behalf of his excellency Mr. Felix Antoine Chis Chumbo, president of the DRC and head of state, the Congalles vision of the future of our I want to congratulate his excellency Mr."},{"t":67,"topic":"United Nations General Assembly","text":"Khalilur Rakman on his election as president of this 81st session of the general assembly. I also pay tribute to her excellency Miss Anelina Bearbuk for the work she accomplished during the previous session. Lastly, I pay tribute in particular to Mr. Antonio Gutish, Secretary General of the United Nations, at a time when his mandate is coming to its end. During a decade marked by wars, the pandemic, climate emergencies, and exacerbated gitical tensions, he constantly defended peace, human dignity, and international Mr. President, the theme of this session, restoring trust, managing the United Nations that delivers for expresses perfectly the challenge that we must collectively address to restore the hope that the UN nurtured when it was created."},{"t":135,"topic":"Multilateral cooperation","text":"for the DRC. This session is another occasion to reaffirm its faith in a multilateralism based upon the unwavering quest for peace and justice which paved the way not to the prosperity of a select few but to the creation of a true common horizon for peoples and generations of the future. This faith, however, calls upon us to be cleareyed about the world's transformations and to ask about the ability of the UN to evolve alongside it. for our peoples have never ceased to believe in the need for international cooperation. A cooperation which at the most difficult times can be promptly mobilized but in other circumstances may seem to drag its feet. When territorial integrity is vigorously defended in one crisis but seems negotiable in another. when the suffering of civilians calls for immediate action in one place but seems less urgent in another."},{"t":204,"topic":"United Nations trust funds","text":"In reality, there can be no lasting trust when the force of our principles varies depending on the people's crises or circumstances. In a world in constant flux, the trust of our peoples in begins when the law is applied uniformly regardless of geography, economic power, or alliances. Our transformation ought to be based upon the need to uphold the charter in its entirety, especially through the respect for the principle of the sovereign equality of states, peaceful dispute settlement, the prohibition of the use of force, respect for territorial integrity and human This ought to be the ambition of the United Nations. Mr. president. It cannot speak of restoring trust toward the UN, let alone of a as long as the UN continues to reflect a world that has ceased to exist."},{"t":269,"topic":"AI governance","text":"The world of 1945 no longer exists. Digital revolution, energy transition, and climate disregulation are now altering equilibria. And yet the institutions charged with managing these changes too often reflect an order that no longer exists. Artificial intelligence today offers one of the most striking examples of this. It has immense potential but also poses risk of new fractures. Its governance should not be the sole remitt of certain powers or corporations. Developing countries ought to be able to participate in defining its rules and to access to the capacities that determine its use. The DRC supports the UN global dialogue on AI governance as well as the creation of a global capacity building fund. Digital divide must not become an intelligence divide. This need for inclusion ought first and foremost to be reflected in global governance."},{"t":334,"topic":"United Nations Security Council reform","text":"Africa has proven itself over time to be a demographic, diplomatic and geopolitical power, a vital one, but it still remains inadequately represented where decisions are being made about the world's future. How can we fail to mention the historic anomaly that is the absence of Africa among the permanent members of the security council? The admission of the African Union to G20 is certainly a major step in the right direction. However, it is not sufficient to meet this need for representation. As a member of the security council 2026 2027, we reaffirm our support for the common African position enshrined in the Ezelini consensus and the seir declaration that is to say two permanent seats for Africa with all of the associated privileges including veto rights as long as they exist and two non-permanent additional in order to make the council more representative, more legitimate and ultimately more effective."},{"t":404,"topic":"Democratic Republic of the Congo international relations","text":"Ive this need for representation goes hand in hand with a need for responsibility and it is in this spirit that the DRC intends to fully exercise its responsibility when it comes to choosing the next general whose mandate ought to be part of the transformation of our organization and help adapt it to the priorities of a world and profound evolution. This same ambition is our driving force within the franophhone world through the candidacy of Miss Juliana Amatulum Mumba for the position of secretary general of the O of the vision of a renewed franophony that is closer to its peoples and capable of strengthening trust between its members and to tackle the challenges we are facing for the DRC. It is precisely in the gap between the trust we are calling to be restored and the transformation that we hope to manage that the real impact of our international commitments is measured. Our country is at the heart of several of these transformations and sometimes at the intersection of their very contradictions."},{"t":473,"topic":"Democratic Republic of the Congo conflict","text":"Mr. President, few situations illustrate so painfully the gap between international commitments and lived reality as that of the east of the DRC. For more than three decades, millions of have been suffering attacks, forced displacement, and bereavement. Territories have been occupied, families Women and girls have suffered sexual violence while children are recruited by armed groups or deprived of education. At the same time, the looting of our resources continues to fuel international trade. My country continues to face a war of aggression led by Rwanda through its proxy, the AFCM23, in violation of its sovereignty, our sovereignty, and our territorial integrity as documented by the UN. The atrocities committed by other armed groups, especially the ADF and KODCO, are exacerbating this humanitarian crisis even further."},{"t":541,"topic":"Democratic Republic of the Congo peace process","text":"To combat this challenge, the DRC has chosen the path of diplomacy without ever abandoning its rights. The peace agreement signed to Washington on June 27, 2025. The commitments made as part of the Doha process and the road map coordinated by the African Union have opened up prospects that we have constantly supported. I commend the United States, Qatar, the African Union, African facilitators, regional partners, and all those who are sincerely striving to restore peace. However, for the sake of truth, we must recognize that for millions of Congolese, this peace remains only a promise. Resolution 2773 of the Security Council has laid out an unambiguous path. It calls for an effective sessation of hostilities, the withdrawal of Rwanda forces from Congalles territory, an end to all support for armed groups, the disengagement of the AFCM23, the dismantling of parallel administrations, the restoration of state authority, unhindered humanitarian access, and the safe and dignified return of displaced persons and refugees."},{"t":613,"topic":"Democratic Republic of the Congo armed groups","text":"But we don't need new texts to replace those that have already been adopted. What we need is their implementation. With regard to the issue of the Democratic Liberation Forces of Rwanda, the FDLR, longsighted by Kegali to justify its military presence in our territory, the DRC is shouldering its responsibility. The protocol signed by the political and military leadership of the FDLR on May 30th, 2026 provides for the disarmament, demobilization, and containment of their combatants with a view toward their repatriation or resettlement without prejudice to potential judicial persecution, prosecution for serious crimes until the movement is disbanded. The repatriation on September 8th with support of Monusco 120 persons associated with the FDLR is a first testament to the protocol's implementation. The issue of the FDLR therefore should no longer serve as a pretext for maintaining foreign military presence in our territory."},{"t":676,"topic":"Democratic Republic of the Congo peace process","text":"The implement coordinated implementation of the mechanisms of Washington, Doha and the African Union must be subject to a precise time frame, independent verification, regular information and clear consequences in case of violations. In this context, Bonusco maintains a vital role in protecting civilians, monitoring the ceasefire, and supporting agreed upon mechanisms. Any change to its presence must be determined by the conditions of security on the ground, the strengthening of national capacity, and the guarantee that no vacuum of power will remain to the detriment of populations. The DRC, for its part, will continue to fully shoulder its responsibility, especially through pursuing reforms of its defense and security institutions, through bolstering state authority, and through reconstruction on territories affected by the conflicts. And because the peace sought after in the sub region ought to go hand in hand with cohesion within our nation, the president of the DRC launched on August 28th a national dialogue for peace, cohesion, and the rebuilding of the state."},{"t":753,"topic":"Democratic Republic of the Congo territorial integrity","text":"This dialogue is open to the political and social forces that are committed to the republic, our constitution, our territorial integrity, and to the rejection of violence. It does not aim to circumvent institutions nor to distribute power. It ought to help us address the structural causes of our vulnerabilities, to consolidate national unity, and to build a state that is more just, more involved, and more protective. Our hand remains outstretched toward all the children of Congo that choose peace, republican debate, and loyalty to their homeland. We Congolese speak to each other with frankness and responsibility, but no internal dialogue can transform an external aggression into a simple domestic dispute. At the same time, no external aggression should absolve us of correcting our own weaknesses. National cohesion and the defense of our territorial integrity are not mutually exclusive but mutually complimentary."},{"t":817,"topic":"Democratic Republic of the Congo mining policy","text":"Because the peace that we seek cannot be limited to a ceasefire. It ought to also help our country regain full control of its future by transform transforming the wealth that is too often gone to fuel conflict into tools for development and shared prosperity. Mr. President, it is another paradox that my country's experience is showing the world that some of its resources that fuel conflicts on its territory are also those that a growing proportion of the transformations of the global economy depend upon. The governance of strategic resources ought to be an issue of peace, development and global security from now on. The energy transition, the electrification of transport, energy storage, as well as the expansion of digital and AI infrastructure are accelerating demand for copper, cobalt, lithium, nickel, and other critical minerals. As the largest global producer of cobalt and a major copper producing power, the DRC is at the heart of the transformation."},{"t":885,"topic":"Democratic Republic of the Congo mining policy","text":"Congolese cobalt is already being used in batteries, power grids, digital equipment, and technologies that are crucial for the decarbonization of the global economy. It would be both unjust and dangerous for added value, jobs, knowhow, and technologies to remain concentrated far away from the communities that are making these changes possible. We cannot build a decarbonized economy through bloodstained minerals and we will not bring about a just transition by reproducing a greenwashed version of our past dependencies. The DRC therefore refuses the old rejects the old model that limits producer countries to crude extraction while processing research technology and the bulk of the profits are concentrated elsewhere. Our ambition is clear. We no longer wish to be simply the basement of the world's economy. We plan to become a workshop, a laboratory, and a sovereign partner."},{"t":949,"topic":"Democratic Republic of the Congo mining policy","text":"&gt;&gt; We'd like to further transform cobalt and copper, process more cobalt and copper on our territory, develop precursors for batteries and industrial components, train our engineers, support our researchers, and include our enterprises in global value chains. We'd like to build together with our African and international partners competitive regional businesses that create jobs, skills, and shared prosperity. This first and foremost entails taking up our own responsibilities. The DRC is pursuing the modernization of mining governance through the transparency of contracts, extractive revenue, and effective beneficiaries. improving mining registries, the deployment of traceability mechanisms, and the fight against fraud. We're also accelerating the formalization of small-cale mining, the regulation of traders, organization of cooperatives, and by securing exploitation zones. The battle against child labor in mines in this regard is a moral and national obligation."},{"t":1015,"topic":"Democratic Republic of the Congo labor","text":"Together with the International Labor Organization, UNICEF, and our other partners, we are strengthening our identification monitoring and remediation mechanisms as well as the training of our inspectors, school attendance of children and economic solutions for their families. Our goal is unambiguous. We need to achieve zero children in the mines. This responsibility is one that lies with the Congolese state, but it also involves businesses, traders, refiners, manufacturers, financial institutions and destination markets. The real proof of a responsible supply chain is not the electric vehicle sold downstream. It is the child who no longer descends into the mines upstream. That is why the DRC proposes creating under UN opaces and together with the African Union as well as producer, processor and consumer countries a global framework for just traceable and resilient critical mineral value chains based upon the sovereignty of producer states."},{"t":1083,"topic":"Democratic Republic of the Congo infrastructure","text":"It ought to guarantee traceability of minerals, responsibility of economic actors, protection of workers and communities as well as a more equitable sharing of added value thanks to local processing and technology transfer. The corridor of Loito ought to become one of the tools to further this ambition. We commend the commitment of Angola, Zambia, the USA, the European Union, the African Development Bank, financial institutions, and this private sector to promote its implementation. The rehabilitation of railway links, the modernization of infrastructure, the facilitation of exchange and energy investments can connect our territories, reduce logistical costs, and stimulate regional trade. But our vision goes far beyond accelerating the export of our raw materials. A corridor that only shortens the path from the mine to the port only reproduces the past."},{"t":1148,"topic":"Democratic Republic of the Congo education","text":"The corridor of Loito ought to become a real backbone for regional industrialization with the support of investors with the help of whom we hope to build sustainable and mutually beneficial partnerships for the well-being of future generations. Mr. President, as you have understood, the transformation we're calling for at the UN is one we have chosen to launch first at home. Convinced that by investing in our people, the main source of wealth of our nation, we will be paving the way toward renewed trust and lasting Since 2019, we have had free primary education, enabling more than 5 million additional children to attend school. In the 2020 2024 school year, more than 21 million children were enrolled in primary school compared with 14.7 four years earlier."},{"t":1215,"topic":"Democratic Republic of the Congo education","text":"This quantitative progress must now be transformed into quality. We are continuing to build and rehabilitate schools. And recently, we've begun to roll out school cafeterias because access is not enough. Every child must be able to learn in a school that is safe, inclusive, well equipped, and open to the tools of our time. This requirement applies especially to girls, children with disabilities, displaced children, and those whose schooling has been jeopardized by conflict. The same ambition guides our health policy. We're continuing the gradual expansion of universal health coverage in particular through free maternity care, improved maternal and newborn care, vaccination, access to essential medicines, the strengthening of the health care workforce, and by expanding social protections. Mr. President, every health crisis confirms the same truth."},{"t":1278,"topic":"Democratic Republic of the Congo health","text":"Health sovereignty is built before emergencies. It is based upon accessible health care systems, robust epidemiological high performing laboratory laboratories, wellunded research and above all the trust of the population. In this regard, the Ebola virus outbreak caused by the bundo strain remains a major test for our country. For the DRC, fighting this epidemic is an absolute priority. After having contained 16 previous outbreaks, the DRC is mobilizing recognized scientific and operational expertise. And thanks to national mobilization and the support of our partners, the response has recently begun producing tangible results. In addition, clinical trials are now underway to evaluate vaccines and treatment for this strain in particular."},{"t":1341,"topic":"Climate disruptions","text":"I'd like to pay tribute to the Congalles and foreign healthcare workers, researchers, communities, and our partners, especially the WH and the Africa Centers for Disease Control and or the Africa CDC for their invaluable support to the DRC and eradicating this disease and strengthening resilience to it. Mr. Presidents, this need for resilience does not stop at the boundaries of health. It is also vital when it comes to climate disruptions whose effects are already putting our societies under growing pressure, flooding, droughts, and erosion. Not to mention population displacement are threatening our stability. In light of these upheavalss, not all countries bear the same responsibility or the same burden. Those who contribute least to global warming often suffer the heaviest consequences. This paradox is all the more striking given that some of these countries are also some of the main custodians of the natural assets upon which our common future depends."},{"t":1408,"topic":"Democratic Republic of the Congo climate finance","text":"The DRC is one of these custodians. It is home to a vital part of the Congo basin which is one of the planet's greatest climate regulators. Its forests, petlands, freshwater and biodiversity provide humanity with considerable ecosystem services. This world heritage will continue to be preserved, but we maintain that the communities that protect it ought to be able to benefit from it. Climate finance in this regard is a fair solution. However, it ought to be accessible, predictable, and proportionate to the services rendered. Indeed, climate justice cannot consist in further indebting those who already bear the cost of damage they did. the least to cause in the DRC. This ambition is taking shape especially through the Kivu Kinshasa green corridor which combines existent preservation, economic development and improve living conditions of the people generating 60 megawatts of electricity."},{"t":1473,"topic":"Democratic Republic of the Congo green economy","text":"This initiative also aims by 2027 to create 25,000 jobs and protect 5,000 square kilometers of natural forest. The climate crisis is also a water crisis. Following the African Water Forum held in Jamina in July, the DRC has proposed the creation of an African coalition for water security, which aims to strengthen regional cooperation and mobilizing the financing needed to make water a driver of development and for the prevention of Mr. President, these transformations require considerable resources. Four years from the 2030 deadline, the Congoles roadmap for accelerating the estimates our needs at more than 7 billion dollars. We are strengthening our domestic revenue and enhancing the quality of public spending. But a country facing war, epidemics, poverty, and climate shock simultaneously cannot close this gap alone."},{"t":1542,"topic":"International development aid","text":"At the same time, official development aid has fallen by more than 23% in real terms in 2025, which is the steepest annual contraction ever recorded. This contraction undermines development efforts and jeopardizes the prevention of crises whose consequences go far beyond national borders. ODA remains indispensable, but it will not be enough. The Sevilla commitment must now translate into better access to concessional financing mobilization of federal development banks and debt relief mechanisms that protect our state's ability to invest. Lastly, no financial architecture can be sustainable without tax justice. International cooperation must combat illicit financial flows, tax evasion, transfer pricing manipulation, and the laundering of revenue from natural resources. Stolen assets must be rapidly identified, frozen, and returned."},{"t":1607,"topic":"Democratic Republic of the Congo resource management","text":"Every penny recovered can fund a vaccine, a a well, or a road. Mr. President, the DRC knows that the trust it calls for restoring on the international stage is earned first through the commitments it keeps on its own soil. That is the goal of our efforts to consolidate peace, strengthen our institutions, and make our natural and human wealth the foundation of shared prosperity. Our experience has taught us, however, that no national transformation can fully bear fruit in an international order in which principles remain unequally applied and in which institutions are not sufficiently adapted to the realities of our time. That is why our ambition for the United Nations is inseparable from what we hold dear for our own country. We want a transformation that inspires confidence and trust because it keeps its promises and trust that makes transformation possible in the long term."},{"t":1671,"topic":"United Nations reform","text":"At a time when humanity hesitates between fragmentation and cooperation, it is up to us to make this ambition our collective responsibility. Restoring trust means applying the law even when it is costly, not only when it is convenient. Supporting transformation means sharing its benefits equitably. Putting the UN at the service of all means ensuring that no people is too far away to be protected or too deprived to be heard or too rich in resources to remain sovereign. The DRC intends to play its full role in this effort. At the heart of Africa, it will pursue its own transformation while contributing to that of our organization. We are convinced that justice rendered to the UN will strengthen the security of all because it is by restoring to institutions the strength of their principles to peoples the proof of our word and future generations the right to hope that we will restore the full meaning of the promise of the UN together."},{"t":1736,"topic":null,"text":"Thank you. On behalf of the assembly, I wish to thank the prime minister, head of government of the Democratic Republic of the Congo."}],"compare":[{"topic":"UN & its reform","share":0.1553,"mean":0.205,"rank":115,"others":170},{"topic":"Democratic Republic of the Congo","share":0.0778,"mean":0.0046,"rank":6,"others":6},{"topic":"International Law & Order","share":0.0392,"mean":0.0605,"rank":101,"others":102},{"topic":"Climate Change","share":0.0389,"mean":0.0428,"rank":78,"others":77},{"topic":"Artificial Intelligence","share":0.0378,"mean":0.0505,"rank":83,"others":83},{"topic":"Humanitarian Aid","share":0.0377,"mean":0.0017,"rank":6,"others":5}]};
